:flex;gap:10px;padding:16px 20px;border-top:1px solid #e3e8e5}.chat-composer textarea{flex:1;resize:none;border:1px solid #d7dfda;border-radius:15px;padding:12px;outline:none}.empty-chat{margin:auto;text-align:center;color:#819088}.empty-chat i{font-size:45px;color:#c4d4cb}@media(max-width:800px){.live-chat-app{grid-template-columns:1fr;height:auto}.chat-inbox{max-height:310px}.chat-workspace{min-height:600px}.chat-workspace-head{align-items:flex-start;flex-direction:column}.admin-bubble{max-width:88%}}
