<div class="live-chat-app">
 <aside class="chat-inbox"><div class="chat-inbox-head"><h1>Live conversations</h1><p>Visitors waiting for a real travel specialist</p></div><div class="chat-session-list" id="session-list"></div></aside>
 <section class="chat-workspace"><header class="chat-workspace-head"><div><strong id="visitor-title">Select a conversation</strong><p id="chat-status" class="text-xs text-gray-500"></p></div><div class="agent-controls"><input id="agent-name" value="<?= htmlspecialchars($_SESSION['admin_username']) ?>" maxlength="80" placeholder="Your display name"><button id="join-chat" type="button" disabled>Join as this name</button><button id="close-chat" type="button" disabled>Close</button></div></header><div class="chat-thread" id="admin-thread"><div class="empty-chat"><i class="fas fa-comments"></i><p>Choose a visitor to begin.</p></div></div><form class="chat-composer" id="admin-chat-form"><textarea id="admin-message" maxlength="2000" rows="2" placeholder="Reply to the visitor…" disabled></textarea><button type="submit" disabled>Send</button></form></section>
</div>
<script>
(()=>{const api='human-chat-api.php',list=document.querySelector('#session-list'),thread=document.querySelector('#admin-thread'),title=document.querySelector('#visitor-title'),status=document.querySelector('#chat-status'),name=document.querySelector('#agent-name'),join=document.querySelector('#join-chat'),close=document.querySelector('#close-chat'),form=document.querySelector('#admin-chat-form'),input=document.querySelector('#admin-message');let active=0,last=0;
const call=async data=>{const r=await fetch(api,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),j=await r.json();if(!r.ok)throw new Error(j.error||'Request failed');return j};
const esc=s=>{const d=document.createElement('div');d.textContent=s;return d.innerHTML};
async function refreshList(){try{const d=await call({action:'list'});list.innerHTML=d.sessions.map(s=>`<button class="chat-session ${+s.id===active?'active':''}" data-id="${s.id}" data-name="${esc(s.visitor_name)}"><strong>${esc(s.visitor_name)}<i>${esc(s.status)}</i></strong><p>${esc(s.last_message||'New conversation')}</p><small>${esc(s.last_activity)}</small></button>`).join('')||'<p class="p-6 text-sm text-gray-500">No conversations yet.</p>';list.querySelectorAll('button').forEach(b=>b.onclick=()=>select(+b.dataset.id,b.dataset.name))}catch(e){}}
function select(id,visitor){active=id;last=0;thread.innerHTML='';title.textContent=visitor;join.disabled=close.disabled=input.disabled=form.querySelector('button').disabled=false;messages();refreshList()}
function add(m){const el=document.createElement('div');el.className=`admin-bubble ${m.sender}`;el.innerHTML=`<strong>${esc(m.sender_name)}</strong><p>${esc(m.message)}</p><small>${esc(m.created_at)}</small>`;thread.append(el);thread.scrollTop=thread.scrollHeight;last=Math.max(last,+m.id)}
async function messages(){if(!active)return;try{const d=await call({action:'messages',session_id:active,after:last});d.messages.forEach(add);status.textContent=`${d.session.status}${d.session.agent_name?' · '+d.session.agent_name:''}`}catch(e){}}
join.onclick=async()=>{if(!active)return;await call({action:'join',session_id:active,agent_name:name.value});messages();refreshList()};close.onclick=async()=>{if(!active)return;await call({action:'close',session_id:active});status.textContent='closed';refreshList()};form.onsubmit=async e=>{e.preventDefault();if(!active||!input.value.trim())return;await call({action:'send',session_id:active,agent_name:name.value,message:input.value.trim()});input.value='';messages();refreshList()};refreshList();setInterval(()=>{refreshList();messages()},3000)})();
</script>
